Object.assign(atlasTranslations,Object.fromEntries([
['Единые цифровые документы','Yagona raqamli hujjatlar','Unified digital documents'],['База данных документов','Hujjatlar ma’lumotlar bazasi','Document database'],['Национальная ДТС','Milliy IUT','National TTP'],['Узбекистан · проверка доверия','O‘zbekiston · ishonchni tekshirish','Uzbekistan · trust verification'],['ДТС РФ','Rossiya IUT','Russian TTP'],['Контур ЭДО · Россия','Kontur EHA · Rossiya','Kontur document exchange · Russia'],['Участники Узбекистана','O‘zbekiston ishtirokchilari','Uzbekistan participants'],['Юридические и физические лица','Yuridik va jismoniy shaxslar','Legal entities and individuals'],['Трансграничный ЭДО','Transchegaraviy EHA','Cross-border document exchange'],['Участники страны','Davlat ishtirokchilari','Country participants'],['Системы ЭДО','Elektron hujjat tizimlari','Document exchange systems'],['Узбекистан · подключённые системы','O‘zbekiston · ulangan tizimlar','Uzbekistan · connected systems'],['Запрос на проверку','Tekshiruv so‘rovi','Verification request'],['Документ / запрос','Hujjat / so‘rov','Document / request'],['Ответ / документ','Javob / hujjat','Response / document'],['Передача','Uzatish','Transfer'],['Учёт документов','Hujjatlarni hisobga olish','Document records'],['Партнёрская ДТС','Hamkor IUT','Partner TTP'],['ДТС Кыргызстана','Qirg‘iziston IUT','Kyrgyzstan TTP'],['Служба проверки требует уточнения','Tekshiruv xizmati aniqlashtirilmoqda','Verification service to be confirmed'],['Оператор требует уточнения','Operator aniqlashtirilmoqda','Operator to be confirmed'],['Партнёр требует уточнения','Hamkor aniqlashtirilmoqda','Partner to be confirmed'],['Система ЭДО Беларуси','Belarus EHA tizimi','Belarus document exchange system'],['Система ЭДО Китая','Xitoy EHA tizimi','China document exchange system'],['Система ЭДО Азербайджана','Ozarbayjon EHA tizimi','Azerbaijan document exchange system'],['ДТС Азербайджана','Ozarbayjon IUT','Azerbaijan TTP'],['Система ЭДО · Казахстан','EHA tizimi · Qozog‘iston','Document exchange system · Kazakhstan'],['Партнёр Кыргызстана','Qirg‘iziston hamkori','Kyrgyzstan partner'],['Партнёрская система ЭДО','Hamkor EHA tizimi','Partner document exchange system'],['Документ передаётся между системами ЭДО. Национальная ДТС Узбекистана обменивается запросом и результатом проверки с иностранной ДТС, возвращает квитанцию в TEHAT.UZ и передаёт сведения в базу документов. Схема показывает общую архитектуру; действующий этап указан в карточке страны.','Hujjat elektron hujjat tizimlari o‘rtasida uzatiladi. O‘zbekiston milliy IUT xorijiy IUT bilan tekshiruv so‘rovi va natijasini almashadi, TEHAT.UZ ga kvitansiya qaytaradi va hujjatlar bazasiga ma’lumot uzatadi. Sxema umumiy arxitekturani ko‘rsatadi; joriy bosqich davlat kartasida berilgan.','Documents pass between document exchange systems. Uzbekistan’s national TTP exchanges verification requests and results with the foreign TTP, returns a receipt to TEHAT.UZ and sends records to the document database. This is the general architecture; the current stage appears in the country card.']
].map(([ru,uz,en])=>[ru,{uz,en}])));

for(const [ru,uz,en] of [['Россия','Rossiya','Russia'],['Казахстан','Qozog‘iston','Kazakhstan'],['Кыргызстан','Qirg‘iziston','Kyrgyzstan'],['Беларусь','Belarus','Belarus'],['Китай','Xitoy','China'],['Азербайджан','Ozarbayjon','Azerbaijan']])atlasTranslations[ru+' · юридические и физические лица']={uz:uz+' · yuridik va jismoniy shaxslar',en:en+' · legal entities and individuals'};

Object.assign(atlasTranslations,Object.fromEntries([
['TEHAT.UZ · трансграничный обмен','TEHAT.UZ · transchegaraviy almashinuv','TEHAT.UZ · cross-border exchange'],['TEHAT.UZ соединяет участников и системы электронного документооборота Узбекистана с иностранными системами. Доставка документа и проверка доверия — связанные процессы: ДТС проверяет подпись и сертификат, а система обмена передаёт документ и возвращает квитанцию.','TEHAT.UZ O‘zbekiston ishtirokchilari va elektron hujjat tizimlarini xorijiy tizimlar bilan bog‘laydi. Hujjat yetkazilishi va ishonch tekshiruvi bog‘liq jarayonlar: IUT imzo va sertifikatni tekshiradi, almashinuv tizimi esa hujjatni uzatadi va kvitansiya qaytaradi.','TEHAT.UZ connects Uzbekistan’s participants and document exchange systems with foreign systems. Delivery and trust verification are related processes: the TTP checks signatures and certificates, while the exchange system transfers documents and returns receipts.'],['Иностранная система ЭДО','Xorijiy EHA tizimi','Foreign document exchange system'],['Оператор страны-партнёра','Hamkor davlat operatori','Partner country operator'],['Зарубежные участники','Xorijiy ishtirokchilar','Foreign participants'],['UNICON.UZ · трансграничный ЭДО','UNICON.UZ · transchegaraviy EHA','UNICON.UZ · cross-border document exchange'],['Подготовка документа','Hujjat tayyorlash','Document preparation'],['Участник создаёт документ и подписывает его электронной подписью.','Ishtirokchi hujjat yaratadi va uni elektron imzo bilan imzolaydi.','The participant creates a document and signs it electronically.'],['Доставка через TEHAT.UZ','TEHAT.UZ orqali yetkazish','Delivery through TEHAT.UZ'],['Система связывает операторов ЭДО и передаёт документ получателю.','Tizim EHA operatorlarini bog‘laydi va hujjatni qabul qiluvchiga yetkazadi.','The system connects document exchange operators and delivers the document to the recipient.'],['Национальная и иностранная ДТС обмениваются запросом и результатом проверки.','Milliy va xorijiy IUT tekshiruv so‘rovi va natijasini almashadi.','National and foreign TTPs exchange verification requests and results.'],['Квитанция и учёт','Kvitansiya va hisobga olish','Receipt and records'],['Результат возвращается участнику, сведения об операции учитываются.','Natija ishtirokchiga qaytariladi, operatsiya ma’lumotlari hisobga olinadi.','The result returns to the participant and the operation is recorded.']
].map(([ru,uz,en])=>[ru,{uz,en}])));
Object.assign(atlasTranslations,Object.fromEntries([
['База учитывает цифровые документы и сведения об операциях. Состав сохраняемых данных и права доступа определяются правилами системы.','Baza raqamli hujjatlar va operatsiyalarni hisobga oladi. Saqlanadigan ma’lumotlar va kirish huquqlari tizim qoidalari bilan belgilanadi.','The database records digital documents and operation details. Stored data and access rights follow system rules.'],
['Национальная ДТС Узбекистана проверяет электронную подпись, целостность документа и статус сертификата. При трансграничной проверке взаимодействует с иностранной службой доверия.','O‘zbekiston milliy IUT elektron imzo, hujjat yaxlitligi va sertifikat holatini tekshiradi. Transchegaraviy tekshiruvda xorijiy ishonch xizmati bilan hamkorlik qiladi.','Uzbekistan’s national TTP verifies electronic signatures, document integrity and certificate status. Cross-border verification involves the foreign trust service.'],
['Партнёрская ДТС принимает запрос проверки и возвращает результат. Конкретная служба зависит от выбранной страны и этапа сотрудничества.','Hamkor IUT tekshiruv so‘rovini qabul qiladi va natijani qaytaradi. Xizmat tanlangan davlat va hamkorlik bosqichiga bog‘liq.','The partner TTP receives verification requests and returns results. The service depends on the country and cooperation stage.'],
['Юридические и физические лица создают и подписывают документы. Они участвуют в обмене через свои системы ЭДО или согласованное прямое подключение.','Yuridik va jismoniy shaxslar hujjat yaratadi va imzolaydi. Ular o‘z EHA tizimlari yoki kelishilgan bevosita ulanish orqali almashinuvda ishtirok etadi.','Legal entities and individuals create and sign documents. They exchange them through their document systems or an agreed direct connection.'],
['TEHAT.UZ связывает отправителя и получателя, передаёт документ в партнёрскую систему и взаимодействует с национальной ДТС. Результат проверки и квитанция возвращаются участнику.','TEHAT.UZ jo‘natuvchi va qabul qiluvchini bog‘laydi, hujjatni hamkor tizimga uzatadi va milliy IUT bilan hamkorlik qiladi. Tekshiruv natijasi va kvitansiya ishtirokchiga qaytariladi.','TEHAT.UZ connects sender and recipient, transfers the document to the partner system and interacts with the national TTP. Verification results and receipts return to the participant.'],
['Иностранная система получает электронный документ и передаёт его своему участнику. Проверка доверия выполняется через соответствующую ДТС, по согласованным правилам.','Xorijiy tizim elektron hujjatni qabul qilib, o‘z ishtirokchisiga yetkazadi. Ishonch tekshiruvi tegishli IUT orqali kelishilgan qoidalar asosida bajariladi.','The foreign system receives the document and delivers it to its participant. Trust verification uses the appropriate TTP under agreed rules.'],
['Получатель использует документ и результат проверки в своём процессе. Обратный обмен проходит по согласованному маршруту.','Qabul qiluvchi hujjat va tekshiruv natijasini o‘z jarayonida ishlatadi. Javob almashinuvi kelishilgan yo‘nalishda amalga oshiriladi.','The recipient uses the document and verification result in their process. Return exchange follows the agreed route.'],
['Подключённые системы ЭДО передают документы в TEHAT.UZ и получают квитанции. Варианты подключения — через роуминг или напрямую; нажмите, чтобы увидеть маршруты.','Ulangan EHA tizimlari hujjatlarni TEHAT.UZ ga uzatadi va kvitansiya oladi. Ulanish rouming orqali yoki bevosita bo‘lishi mumkin; yo‘nalishlarni ko‘rish uchun bosing.','Connected document systems send documents to TEHAT.UZ and receive receipts. Connections can use roaming or direct access; click to explore routes.']
].map(([ru,uz,en])=>[ru,{uz,en}])));

Object.assign(atlasTranslations,{"Центр управления проектами цифрового правительства":{"uz":"Raqamli hukumat loyihalarini boshqarish markazi","en":"Digital Government Project Management Center"},"Таможенный комитет Республики Узбекистан":{"uz":"O‘zbekiston Respublikasi Bojxona qo‘mitasi","en":"Customs Committee of the Republic of Uzbekistan"},"Научно-информационный центр новых технологий":{"uz":"Yangi texnologiyalar ilmiy-axborot markazi","en":"Scientific Information Center for New Technologies"},"Агентство «Узархив»":{"uz":"O‘zarxiv agentligi","en":"Uzarchive Agency"},"Сотрудничество планируется":{"uz":"Hamkorlik rejalashtirilmoqda","en":"Cooperation is planned"},"Этап взаимодействия уточняется":{"uz":"Hamkorlik bosqichi aniqlashtirilmoqda","en":"Cooperation stage to be confirmed"},"Архивное направление":{"uz":"Arxiv yo‘nalishi","en":"Archival cooperation"},"Центр управления проектами цифрового правительства · защищённая проверка":{"uz":"Raqamli hukumat loyihalarini boshqarish markazi · himoyalangan tekshiruv","en":"Digital Government Project Management Center · secure verification"},"IUT соединяет организации с инфраструктурой доверия. Интеграция с Soliq.uz проведена. Сотрудничество с Центром управления проектами цифрового правительства и подключение Temir yo‘l планируются. Этап взаимодействия с Таможенным комитетом уточняется.":{"uz":"IUT tashkilotlarni ishonch infratuzilmasi bilan bog‘laydi. Soliq.uz bilan integratsiya bajarilgan. Raqamli hukumat loyihalarini boshqarish markazi bilan hamkorlik va Temir yo‘l bilan integratsiya rejalashtirilmoqda. Bojxona qo‘mitasi bilan hamkorlik bosqichi aniqlashtirilmoqda.","en":"TTP connects organizations to the trust infrastructure. Soliq.uz is integrated. Cooperation with the Digital Government Project Management Center and integration with the railway are planned. The Customs Committee cooperation stage is to be confirmed."},"Схема учёта цифровых документов и результатов обмена. Добавлены Центр управления проектами цифрового правительства и агентство «Узархив». Сотрудничество с центром планируется; этап и порядок взаимодействия с агентством уточняются.":{"uz":"Raqamli hujjatlar va almashinuv natijalarini hisobga olish sxemasi. Raqamli hukumat loyihalarini boshqarish markazi va O‘zarxiv agentligi qo‘shildi. Markaz bilan hamkorlik rejalashtirilmoqda; agentlik bilan hamkorlik bosqichi va tartibi aniqlashtirilmoqda.","en":"Digital document and exchange record diagram. The Digital Government Project Management Center and Uzarchive Agency have been added. Cooperation with the center is planned; the agency’s cooperation stage and procedures are to be confirmed."},"Сотрудничество планируется. Показан предполагаемый принцип проверки: хэш помогает проверить целостность, но сам по себе не шифрует документ. Электронная подпись и сертификат проверяются в инфраструктуре доверия. Точный протокол интеграции уточняется.":{"uz":"Hamkorlik rejalashtirilmoqda. Sxema taxminiy tekshiruv jarayonini ko‘rsatadi: xesh hujjat yaxlitligini tekshiradi, uni shifrlamaydi. Elektron imzo va sertifikat ishonch infratuzilmasida tekshiriladi. Integratsiya protokoli aniqlashtirilmoqda.","en":"Cooperation is planned. This illustrative verification process uses a hash to check integrity, not encrypt the document. The signature and certificate are checked by the trust infrastructure. The integration protocol is to be confirmed."},"Архивное направление единой базы цифровых данных. Этап взаимодействия и состав передаваемых сведений уточняются. Схема показывает предполагаемую связь, а не действующее подключение.":{"uz":"Yagona raqamli ma’lumotlar bazasining arxiv yo‘nalishi. Hamkorlik bosqichi va uzatiladigan ma’lumotlar tarkibi aniqlashtirilmoqda. Sxema amaldagi ulanishni emas, taxminiy aloqani ko‘rsatadi.","en":"Archival cooperation for the unified digital data repository. The cooperation stage and exchanged data are to be confirmed. This diagram shows a proposed connection."}});

Object.assign(atlasTranslations,{"ДТС · проверка доверия и запись результата":{"uz":"IUT · ishonchni tekshirish va natijani qayd etish","en":"TTP · trust verification and result recording"},"ДТС получает запрос проверки, проверяет целостность документа, электронную подпись и статус сертификата. Результат связывается с идентификатором операции и передаётся в базу. Это пояснительная архитектура; конкретный протокол определяется интеграцией.":{"uz":"IUT tekshiruv so‘rovini oladi, hujjat yaxlitligi, elektron imzo va sertifikat holatini tekshiradi. Natija operatsiya identifikatori bilan bog‘lanib bazaga uzatiladi. Bu tushuntiruvchi arxitektura; aniq protokol integratsiyada belgilanadi.","en":"TTP receives a verification request and checks document integrity, the electronic signature and certificate status. The result is linked to the operation ID and sent to the repository. This explanatory architecture depends on the agreed integration protocol."},"Запрос проверки":{"uz":"Tekshiruv so‘rovi","en":"Verification request"},"Запрос содержит сведения, необходимые для проверки, и идентификатор для сопоставления ответа с операцией.":{"uz":"So‘rov tekshirish uchun zarur ma’lumotlar va javobni operatsiyaga bog‘lash identifikatorini o‘z ichiga oladi.","en":"The request carries the information needed for verification and an ID to match the response to the operation."},"Целостность документа":{"uz":"Hujjat yaxlitligi","en":"Document integrity"},"Сравнение цифровых отпечатков позволяет обнаружить изменение документа. Хэш не шифрует содержимое.":{"uz":"Raqamli izlarni taqqoslash hujjat o‘zgarishini aniqlaydi. Xesh mazmunni shifrlamaydi.","en":"Comparing digital fingerprints detects document changes. A hash does not encrypt the content."},"Проверяется соответствие электронной подписи документу и сертификату. Одна целостность без проверки подписи не подтверждает подписанта.":{"uz":"Elektron imzoning hujjat va sertifikatga mosligi tekshiriladi. Faqat yaxlitlik imzolovchini tasdiqlamaydi.","en":"The signature is checked against the document and certificate. Integrity alone does not verify the signer."},"Статус сертификата":{"uz":"Sertifikat holati","en":"Certificate status"},"Срок действия · OCSP / CRL":{"uz":"Amal qilish muddati · OCSP / CRL","en":"Validity period · OCSP / CRL"},"Проверяются срок действия и сведения об отзыве сертификата. Способ получения статуса зависит от подключённой инфраструктуры.":{"uz":"Sertifikat muddati va bekor qilinganligi tekshiriladi. Holatni olish usuli ulangan infratuzilmaga bog‘liq.","en":"Validity and revocation information are checked. The status retrieval method depends on the connected infrastructure."},"Подтверждено / не подтверждено":{"uz":"Tasdiqlangan / tasdiqlanmagan","en":"Confirmed / not confirmed"},"Положительный либо отрицательный результат и причина возвращаются по согласованному протоколу. Ошибка проверки не должна отображаться как успешный результат.":{"uz":"Ijobiy yoki salbiy natija va sababi kelishilgan protokol bo‘yicha qaytariladi. Tekshiruv xatosi muvaffaqiyat sifatida ko‘rsatilmaydi.","en":"A positive or negative result and its reason are returned under the agreed protocol. A verification failure must not appear as success."},"Идентификатор · статус · время":{"uz":"Identifikator · holat · vaqt","en":"ID · status · time"},"Сведения о результате связываются с документом и операцией. Состав сохраняемых данных определяется правилами базы.":{"uz":"Natija ma’lumotlari hujjat va operatsiya bilan bog‘lanadi. Saqlanadigan ma’lumotlar tarkibi baza qoidalarida belgilanadi.","en":"The result is linked to the document and operation. Repository rules determine what information is stored."},"База · жизненный цикл записи":{"uz":"Baza · qaydning hayotiy sikli","en":"Repository · record lifecycle"},"Показан понятный маршрут учёта: поступление сведений, идентификация, запись статуса, журнал и доступ к результату. Срок хранения и права доступа определяются правилами системы.":{"uz":"Hisobga olish yo‘li: ma’lumotni olish, identifikatsiya, holatni qayd etish, jurnal va natijaga kirish. Saqlash muddati va kirish huquqlari tizim qoidalarida belgilanadi.","en":"The record flow covers receiving data, identification, recording status, logging and retrieving results. System rules determine retention and access rights."},"Идентификация записи":{"uz":"Qaydni identifikatsiya qilish","en":"Record identification"},"Контроль доступа":{"uz":"Kirish nazorati","en":"Access control"},"По правилам системы":{"uz":"Tizim qoidalari bo‘yicha","en":"Under system rules"},"Поиск и ответ":{"uz":"Qidiruv va javob","en":"Lookup and response"},"Квитанции · подтверждение и история":{"uz":"Kvitansiyalar · tasdiqlash va tarix","en":"Receipts · acknowledgement and history"},"Квитанция связывает ответ с операцией. Журнал помогает проследить статус и время событий. Подтверждение доставки и положительный результат проверки подписи — разные сведения.":{"uz":"Kvitansiya javobni operatsiyaga bog‘laydi. Jurnal holat va voqealar vaqtini kuzatishga yordam beradi. Yetkazish tasdig‘i va imzo tekshiruvining ijobiy natijasi alohida ma’lumotlardir.","en":"A receipt links a response to an operation. The log tracks status and event times. Delivery acknowledgement and successful signature verification are separate facts."},"Предполагаемое архивное направление: согласование состава сведений, подготовка передачи и подтверждение приёма. Этап сотрудничества, сроки хранения и технический протокол уточняются.":{"uz":"Taxminiy arxiv yo‘nalishi: ma’lumotlar tarkibini kelishish, uzatishga tayyorlash va qabulni tasdiqlash. Hamkorlik bosqichi, saqlash muddatlari va texnik protokol aniqlashtirilmoqda.","en":"Proposed archival cooperation: agree on the data, prepare the transfer and acknowledge receipt. The cooperation stage, retention periods and technical protocol are to be confirmed."},"Согласование состава":{"uz":"Tarkibni kelishish","en":"Agree data scope"},"Подготовка передачи":{"uz":"Uzatishga tayyorlash","en":"Prepare transfer"}});

for (const [key,ru] of [['Mahalliy tashkilotlar bilan hamkorlik','Сотрудничество с местными организациями'],['Xorijiy mamlakatlar bilan hamkorlik','Сотрудничество с зарубежными странами'],['Yagona raqamli ma’lumotlar bazasi','Единая база цифровых данных']]) atlasTranslations[key]={...atlasTranslations[key],ru};

Object.assign(atlasTranslations,{"Запрос на проверку · RFC 3029":{"uz":"Tekshiruv so‘rovi · RFC 3029","en":"Verification request · RFC 3029"},"RFC 3029 · как работает проверка ДТС":{"uz":"RFC 3029 · IUT tekshiruvi qanday ishlaydi","en":"RFC 3029 · how TTP verification works"},"Открыть описание RFC 3029 ↗":{"uz":"RFC 3029 tavsifini ochish ↗","en":"Read RFC 3029 ↗"},"RFC 3029 описывает запросы и ответы службы DVCS для проверки подписанных документов и сертификатов. Результат может оформляться сертификатом проверки данных DVC. Это экспериментальная спецификация; применение в конкретном подключении определяется согласованным протоколом.":{"uz":"RFC 3029 imzolangan hujjatlar va sertifikatlarni tekshirish uchun DVCS so‘rov va javoblarini tavsiflaydi. Natija DVC ma’lumotlarni tekshirish sertifikati sifatida rasmiylashtirilishi mumkin. Bu eksperimental spetsifikatsiya; ulanishda qo‘llanishi kelishilgan protokolga bog‘liq.","en":"RFC 3029 describes DVCS requests and responses for validating signed documents and certificates. Results may be issued as a data validation certificate (DVC). This is an experimental specification; its use in a particular connection depends on the agreed protocol."}});

Object.assign(atlasTranslations,{"Значок файла движется по маршруту обмена. Зелёная отметка показывает подтверждённый результат в демонстрационном сценарии. Нажмите на блок для пояснения; анимация не отображает реальные операции.":{"uz":"Fayl belgisi almashinuv yo‘nalishi bo‘ylab harakatlanadi. Yashil belgi namoyish ssenariysidagi tasdiqlangan natijani ko‘rsatadi. Izoh uchun blokni bosing; animatsiya real operatsiyalarni aks ettirmaydi.","en":"The file icon travels along the exchange route. A green check indicates a confirmed result in the demonstration scenario. Click a block for details; the animation does not show live operations."}});

